// ⓪ ENTRADA · LLAVE · PRUEBA DE PIEZA · J7(pieza) · CC#1 · 2026-10-14 · flujo `zero-risk/jefatura-prueba-pieza` (INACTIVO). Revisa una pieza YA PRODUCIDA con la puerta de la jefatura; no produce nada.
// Solo valida: la llave de despacho, `dry_run` booleano (ausente NO se lee como real ni como seco) y lo mínimo de la pieza. Nada de aquí paga.
const w = $input.first().json || {}
const body = w.body && typeof w.body === 'object' && !Array.isArray(w.body) ? w.body : {}
const headers = w.headers && typeof w.headers === 'object' ? w.headers : {}
const esperada = String($env.SALA_DISPATCH_KEY || '').trim()
if (!esperada) throw new Error('PRUEBA_PIEZA_CERRADA · el motor no tiene la llave de despacho (SALA_DISPATCH_KEY) · el flujo queda cerrado · E67.')
const recibida = String(headers['x-sala-dispatch-key'] || '')
let ok = recibida.length === esperada.length
for (let i = 0; i < esperada.length; i++) ok = recibida.charCodeAt(i) === esperada.charCodeAt(i) && ok
if (!ok) throw new Error('PRUEBA_PIEZA_PROCEDENCIA_INVALIDA · llave de despacho ausente o incorrecta · E67.')
if (typeof body.dry_run !== 'boolean') throw new Error('PRUEBA_PIEZA_SIN_DRY_RUN · dry_run debe ser booleano (true o false) · se DETIENE antes de abrir nada')
if (typeof body.client_id !== 'string' || !/^[A-Za-z0-9_-]{3,80}$/.test(body.client_id)) throw new Error('PRUEBA_PIEZA_CLIENTE_INVALIDO · client_id debe ser texto simple (letras, números, guion) · se DETIENE')
if (typeof body.texto !== 'string' || !body.texto.trim()) throw new Error('PRUEBA_PIEZA_SIN_TEXTO · falta el texto de la pieza · se DETIENE')
if (typeof body.artifact_id !== 'string' || !/^[A-Za-z0-9_.:-]{3,120}$/.test(body.artifact_id)) throw new Error('PRUEBA_PIEZA_ARTEFACTO_INVALIDO · artifact_id debe ser texto simple y único por pieza · se DETIENE')
const lista = (v) => (Array.isArray(v) ? v : [])
return [{ json: {
  client_id: body.client_id,
  artifact_id: body.artifact_id,
  journey_id: typeof body.journey_id === 'string' && body.journey_id ? body.journey_id : null,
  dry_run: body.dry_run,
  texto: body.texto,
  familia: typeof body.familia === 'string' && body.familia ? body.familia : 'post_img',
  imagenes: lista(body.imagenes).filter((u) => typeof u === 'string'),
  contexto: lista(body.contexto).filter((c) => c && typeof c.titulo === 'string' && typeof c.texto === 'string'),
  productores: lista(body.productores).filter((p) => p && typeof p.donde === 'string' && typeof p.agente === 'string'),
  marcas_heredadas: lista(body.marcas_heredadas).filter((m) => typeof m === 'string'),
  tope_restante_usd: typeof body.tope_restante_usd === 'number' && Number.isFinite(body.tope_restante_usd) && body.tope_restante_usd >= 0 ? body.tope_restante_usd : null,
  simulacion: body.dry_run === true && body.simulacion && typeof body.simulacion === 'object' ? body.simulacion : null,
} }]

// JEF · armar · PRUEBA DE PIEZA · J7(pieza) · CC#1 · 2026-10-14 · arma la entrada de la ruta con la pieza que llegó por el webhook. NO lanza: si algo no cuadra, `abrir = false`.
// `devolver_a = ninguno`: el resultado queda en `jefatura_revisiones` (la bandeja de la pieza la escribe la oficina en J8a, no este flujo). Con `dry_run = true` puede traer `simulacion`.
const CFG = {"max_sondeos":22,"tipo":"pieza","plazo_s":1200,"cada_s":60}
const jef = { fase: 'no_abre', motivo: '', plazo_fin: Date.now() + CFG.plazo_s * 1000 }
const e = $('⓪ Entrada · llave').first().json
const sobre = {
  artifact_type: 'pieza',
  artifact_id: e.artifact_id,
  client_id: e.client_id,
  journey_id: e.journey_id,
  payload: {
    texto: e.texto,
    familia: e.familia,
    dry_run: e.dry_run,
    devolver_a: { tipo: 'ninguno', destino: '' },
    chequeos_previos: { pasaron: true, necesita_humano: false, marcas: [] },
    ...(e.contexto.length ? { contexto: e.contexto } : {}),
    ...(e.imagenes.length ? { imagenes: e.imagenes } : {}),
    ...(e.productores.length ? { productores: e.productores } : {}),
    ...(e.marcas_heredadas.length ? { marcas_heredadas: e.marcas_heredadas } : {}),
    ...(e.tope_restante_usd !== null ? { tope_restante_usd: e.tope_restante_usd } : {}),
    ...(e.simulacion ? { simulacion: e.simulacion } : {}),
  },
}
return [{ json: { jef: { ...jef, fase: 'abrir', motivo: '' }, abrir: true, sobre } }]

// JEF · ¿cómo abrió? · J7 · CC#1 · 2026-10-14 · lo que contestó `POST /api/jefatura/revisiones` (abrir). NUNCA lanza: cualquier cosa rara queda como fase `error` y el productor sigue como hoy.
// Fases: cerrada (la ruta ya cerró) · esperar (hay un turno de agente por despertar) · espera_sin_turno (la revisión ya existía y sigue abierta o cerró: se lee) · no_abre (409: apagada, tipo no activo, fuera del ensayo, sin otra vuelta…) · error.
const CFG = {"max_sondeos":22,"tipo":"pieza","plazo_s":1200,"cada_s":60}
const s = $('JEF · armar').first().json
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' && !Array.isArray(r.body) ? r.body : {}
const jef = { ...s.jef }
if (status === 200 && b.accion === 'cerrado' && b.revision_id) {
  Object.assign(jef, { fase: 'cerrada', revision_id: String(b.revision_id), salida: b.salida && typeof b.salida === 'object' ? b.salida : null, resultado: b.resultado || null })
} else if (status === 200 && b.accion === 'esperar' && b.revision_id && b.turno && typeof b.turno === 'object') {
  Object.assign(jef, { fase: 'esperar', revision_id: String(b.revision_id), turno: b.turno })
} else if (status === 200 && b.accion === 'ya_existia' && b.revision_id) {
  Object.assign(jef, { fase: 'espera_sin_turno', revision_id: String(b.revision_id), estado_previo: b.estado || null })
} else if (status === 409) {
  Object.assign(jef, { fase: 'no_abre', motivo: String(b.motivo || b.error || '409') })
} else {
  const corte = r.error && typeof r.error === 'object' ? String(r.error.message || r.error.name || 'la llamada se cortó') : null
  Object.assign(jef, { fase: 'error', http: Number.isFinite(status) ? status : null, motivo: String(b.error || b.detalle || corte || ('HTTP ' + String(r.statusCode))).slice(0, 300) })
}
return [{ json: { jef } }]

// JEF · ¿cerró? · J7 · CC#1 · 2026-10-14 · lo que contestó `POST /api/jefatura/revisiones` (leer). NUNCA lanza.
// cerrada = estado terminal con su salida · seguir = todavía abierta y queda plazo · plazo = se acabó el tiempo (lo que llegue tarde NO se guarda) · error = cerró sin salida.
// Un fallo pasajero de la lectura (5xx, red) no corta la espera: se sigue sondeando hasta el plazo o el tope de sondeos.
const CFG = {"max_sondeos":22,"tipo":"pieza","plazo_s":1200,"cada_s":60}
const base = $('JEF · ¿cómo abrió?').first().json.jef
const r = $input.first().json || {}
const status = Number(r.statusCode)
const b = r.body && typeof r.body === 'object' && !Array.isArray(r.body) ? r.body : {}
const TERMINALES = ['cerrada', 'cerrada_por_tope', 'fallida']
const sondeos = Number($runIndex) + 1
const jef = { ...base, sondeos }
if (status === 200 && TERMINALES.indexOf(b.estado) !== -1) {
  if (b.salida && typeof b.salida === 'object') Object.assign(jef, { fase: 'cerrada', salida: b.salida, resultado: b.resultado || null })
  else Object.assign(jef, { fase: 'error', motivo: 'la revisión cerró (' + String(b.estado) + ') pero la lectura no trajo su salida' })
} else if (Date.now() > Number(base.plazo_fin) || sondeos >= CFG.max_sondeos) {
  Object.assign(jef, { fase: 'plazo', motivo: 'se acabó la espera (' + String(CFG.plazo_s) + ' s) sin que la revisión cerrara: lo que llegue tarde no se guarda' })
} else {
  Object.assign(jef, { fase: 'seguir' })
}
return [{ json: { jef } }]

// JEF · aplicar · PRUEBA DE PIEZA · J7(pieza) · CC#1 · 2026-10-14 · el resumen de lo que pasó (el flujo no entrega a nadie: se lee en la ejecución y en `jefatura_revisiones`).
const CFG = {"max_sondeos":22,"tipo":"pieza","plazo_s":1200,"cada_s":60}
const entrada = $input.first().json || {}
const jef = entrada.jef && typeof entrada.jef === 'object' ? entrada.jef : {}
const sal = jef.salida && typeof jef.salida === 'object' ? jef.salida : null
return [{ json: {
  fase: jef.fase || 'no_abre',
  motivo: jef.motivo || null,
  revision_id: jef.revision_id || null,
  resultado: sal ? String(sal.resultado || '') : null,
  marcas: sal && sal.marcas ? sal.marcas : null,
  desacuerdos: sal && Array.isArray(sal.desacuerdos) ? sal.desacuerdos : [],
  costo_usd: sal && typeof sal.costo_usd === 'number' ? sal.costo_usd : null,
  simulado: sal ? sal.simulado === true : null,
} }]
